import hashlib
import json
from pathlib import Path
from jsonschema import ValidationError
from jsonschema.validators import validator_for

directory = Path('/tmp/cv-0636-07-primary-path').read_text().strip()
directory = Path(directory)
result = {'emitter': 'source Python 3.12.3 / Pydantic 2.14.3', 'directory': str(directory), 'schemas': {}}
for name, path in [('runtime', directory/'schema.json'), ('published', Path('docs/reference/cv_manage_view.schema.json'))]:
    schema = json.loads(path.read_text())
    cls = validator_for(schema)
    cls.check_schema(schema)
    validator = cls(schema)
    cases = {}
    for fixture in sorted(directory.glob('*.json')):
        if fixture.stem == 'schema':
            continue
        expected = 'rejected' if fixture.stem.startswith('invalid') else 'accepted'
        try:
            validator.validate(json.loads(fixture.read_text()))
            actual = 'accepted'
        except ValidationError:
            actual = 'rejected'
        assert actual == expected, (name, fixture, expected, actual)
        cases[fixture.stem] = {'expected': expected, 'actual': actual, 'sha256': hashlib.sha256(fixture.read_bytes()).hexdigest()}
    result['schemas'][name] = {'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'cases': cases}
floor_path = Path('/tmp/cv-0636-07-floor-schema-only.json')
floor_schema = json.loads(floor_path.read_text())
validator_for(floor_schema).check_schema(floor_schema)
result['floor_schema_only'] = {'sha256': hashlib.sha256(floor_path.read_bytes()).hexdigest(), 'metaschema_valid': True, 'actual_floor_corpus_validation': 'blocked by pre-existing Resource subclass import failure; not substituted with primary emissions'}
Path('/tmp/cv-0636-07-receipts/schema-cases.json').write_text(json.dumps(result, indent=2)+'\n')
print('Primary actual emissions: runtime and published each accept 10, reject 15. Floor schema-only metaschema valid; floor corpus blocked.')
